begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('ac2e0000-0000-4000-8000-000000000001','care-sources@example.test','{}');
update profiles set is_active=true,full_name='Synthetic care source DVM' where id='ac2e0000-0000-4000-8000-000000000001';
insert into user_roles(user_id,role) values('ac2e0000-0000-4000-8000-000000000001','DVM'),('ac2e0000-0000-4000-8000-000000000001','ADMIN');
create temp table fx(k text primary key,id uuid);create temp table data(k text primary key,v jsonb);grant all on fx,data to authenticated;
insert into fx select k,gen_random_uuid() from unnest(array['blood-default','vaccine-default','blood-plan','vaccine-plan','lab','planned-lab','historical-vaccine','vaccine','lot','receipt','invoice','completion']) k;
set local role authenticated;select set_config('request.jwt.claims','{"role":"authenticated","sub":"ac2e0000-0000-4000-8000-000000000001"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Care Sources','+12025550188','synthetic-care-sources@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic source patient','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic source sibling','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into data values('blood-default','{"care_key":"synthetic-bloodwork","name":"Synthetic quarterly bloodwork","care_kind":"bloodwork","interval_amount":3,"interval_unit":"months","anchor_mode":"completed_care","month_end":"clamp","active":true,"review_note":"Synthetic clinical review"}');
select save_recurring_care_template(gen_random_uuid(),(select id from fx where k='blood-default'),null,(select v from data where k='blood-default'));
select save_recurring_care_template(gen_random_uuid(),(select id from fx where k='vaccine-default'),null,'{"care_key":"synthetic-vaccine","name":"Synthetic vaccine follow-up","care_kind":"vaccine","interval_amount":1,"interval_unit":"years","anchor_mode":"completed_care","month_end":"clamp","active":true,"review_note":"Synthetic clinical review"}');
insert into data values('blood-values',jsonb_build_object('template_id',(select id from fx where k='blood-default'),'template_version',1,'name','Synthetic quarterly bloodwork','interval_amount',3,'interval_unit','months','anchor_mode','completed_care','month_end','clamp','anchor_on','2026-01-31','due_on','2026-04-30','status','current','reminders_enabled',false,'override_reason','','review_note','Synthetic reviewed bloodwork plan','replace_anchor_evidence',false));
select save_patient_care_plan(gen_random_uuid(),(select id from fx where k='blood-plan'),(select id from fx where k='pet'),null,(select v from data where k='blood-values'));
select save_patient_care_plan(gen_random_uuid(),(select id from fx where k='vaccine-plan'),(select id from fx where k='pet'),null,(select v||jsonb_build_object('template_id',(select id from fx where k='vaccine-default'),'name','Synthetic vaccine follow-up','interval_amount',1,'interval_unit','years','due_on','2027-01-31') from data where k='blood-values'));
select save_patient_lab_order((select id from fx where k='planned-lab'),(select id from fx where k='pet'),null,'{"test_name":"Synthetic planned lab","status":"planned","due_date":"2026-02-28"}','');
select throws_ok($$select preview_care_plan_completion((select id from fx where k='blood-plan'),(select id from fx where k='pet'),1,'lab',(select id from fx where k='planned-lab'),1)$$,'PT409',null,'Planned lab is not evidence of completed care');
select save_patient_lab_order((select id from fx where k='lab'),(select id from fx where k='pet'),null,'{"test_name":"Synthetic actual bloodwork","status":"resulted","collected_date":"2026-02-28","result_date":"2026-03-02"}','');
select is(preview_care_plan_completion((select id from fx where k='blood-plan'),(select id from fx where k='pet'),1,'lab',(select id from fx where k='lab'),1)->>'completed_on','2026-02-28','Bloodwork uses actual collection date rather than later result date');
select is(preview_care_plan_completion((select id from fx where k='blood-plan'),(select id from fx where k='pet'),1,'lab',(select id from fx where k='lab'),1)->>'next_due_on','2026-05-28','Quarterly bloodwork advances by calendar months');
select throws_ok($$select preview_care_plan_completion((select id from fx where k='blood-plan'),(select id from fx where k='pet'),1,'lab',(select id from fx where k='lab'),2)$$,'PT409',null,'Selected evidence version must match the actual lab');
select throws_ok($$select preview_care_plan_completion((select id from fx where k='blood-plan'),(select id from fx where k='other'),1,'lab',(select id from fx where k='lab'),1)$$,'PT409',null,'Sibling lab cannot complete another patient plan');
select throws_ok($$select preview_care_plan_completion((select id from fx where k='vaccine-plan'),(select id from fx where k='pet'),1,'lab',(select id from fx where k='lab'),1)$$,'23514',null,'Lab evidence cannot fulfill vaccine follow-up');
select save_recurring_care_template(gen_random_uuid(),(select id from fx where k='blood-default'),1,(select v||'{"interval_amount":1,"interval_unit":"years","review_note":"Synthetic annual default review"}' from data where k='blood-default'));
select is(read_patient_care_plan((select id from fx where k='blood-plan'),(select id from fx where k='pet'))#>>'{plan,interval_amount}','3','Default update does not silently change the patient interval');
select is(read_patient_care_plan((select id from fx where k='blood-plan'),(select id from fx where k='pet'))#>>'{plan,template_version}','1','Existing reviewed patient snapshot remains on its original version');
insert into data values('completion-values',jsonb_build_object('source_kind','lab','source_id',(select id from fx where k='lab'),'source_version',1,'review_note','Synthetic actual collected bloodwork reviewed'));
select complete_patient_care_plan((select id from fx where k='completion'),(select id from fx where k='blood-plan'),(select id from fx where k='pet'),1,(select v from data where k='completion-values'));
select is(read_patient_care_plan((select id from fx where k='blood-plan'),(select id from fx where k='pet'))#>>'{plan,anchor_on}','2026-02-28','Completed-care recurrence replaces the calendar anchor with actual collection');
select is(jsonb_array_length(list_care_completion_sources((select id from fx where k='pet'),'lab',null,50,(select id from fx where k='blood-plan'))->'rows'),0,'Already-linked physical lab is removed from this plan source picker');
select save_patient_lab_order((select id from fx where k='lab'),(select id from fx where k='pet'),1,'{"test_name":"Synthetic actual bloodwork","status":"resulted","collected_date":"2026-03-01","result_date":"2026-03-02"}','Synthetic date correction after evidence review');
select is(read_patient_care_plan((select id from fx where k='blood-plan'),(select id from fx where k='pet'))#>>'{plan,status}','proposed','Changing completed lab evidence pauses automatic care pending review');
select is(complete_patient_care_plan((select id from fx where k='completion'),(select id from fx where k='blood-plan'),(select id from fx where k='pet'),1,(select v from data where k='completion-values'))->'completion'->>'completed_on','2026-02-28','Correction preserves exact historical receipt and original collection evidence');
-- Native vaccination uses the original stock, billing and alert-review workflow.
insert into fx select 'product',id from save_catalog_product(null,null,'Synthetic actual vaccine','vaccine','Synthetic manufacturer','dose',100,true);
select receive_inventory((select id from fx where k='receipt'),(select id from fx where k='lot'),(select id from fx where k='product'),'SYNTHETIC-VAX',current_date+365,'Synthetic clinic',2,'Synthetic opening stock');
select create_billing_invoice((select id from fx where k='invoice'),(select id from fx where k='client'));
insert into data values('vax-values',jsonb_build_object('pet_id',(select id from fx where k='pet'),'lot_id',(select id from fx where k='lot'),'invoice_id',(select id from fx where k='invoice'),'quantity',1,'dose','1 mL','route','SC','site','Synthetic site','veterinarian','Synthetic source DVM','veterinarian_license','SYNTHETIC','administered_at','2026-03-31T18:00Z','next_due_on','2027-03-31','alert_review',jsonb_build_object('source_hash',read_patient_treatment_alerts((select id from fx where k='pet'))->>'source_hash','acknowledged',true)));
select record_patient_treatment((select id from fx where k='vaccine'),(select v from data where k='vax-values'));
select record_patient_treatment((select id from fx where k='historical-vaccine'),jsonb_build_object('pet_id',(select id from fx where k='pet'),'historical',true,'kind','vaccine','product_name','Synthetic outside vaccine','manufacturer','','lot_number','SYNTHETIC-OUTSIDE','expires_on',null,'quantity',1,'dose','1 mL','route','SC','site','','veterinarian','Synthetic outside DVM','veterinarian_license','','administered_at','2026-03-31T18:00Z','next_due_on',null,'source','Synthetic historical record'));
select is(jsonb_array_length(list_care_completion_sources((select id from fx where k='pet'),'vaccine',null,50,(select id from fx where k='vaccine-plan'))->'rows'),1,'Vaccine completion picker contains native administration only');
select throws_ok($$select preview_care_plan_completion((select id from fx where k='vaccine-plan'),(select id from fx where k='pet'),1,'vaccine',(select id from fx where k='historical-vaccine'),1)$$,'PT409',null,'Historical import cannot fulfill new completed-care recurrence');
select is(preview_care_plan_completion((select id from fx where k='vaccine-plan'),(select id from fx where k='pet'),1,'vaccine',(select id from fx where k='vaccine'),1)->>'next_due_on','2027-03-31','Annual vaccine follow-up uses the actual administration date');
select throws_ok($$select preview_care_plan_completion((select id from fx where k='blood-plan'),(select id from fx where k='pet'),3,'vaccine',(select id from fx where k='vaccine'),1)$$,'23514',null,'Proposed or corrected care cannot be completed without fresh DVM review');
select complete_patient_care_plan(gen_random_uuid(),(select id from fx where k='vaccine-plan'),(select id from fx where k='pet'),1,jsonb_build_object('source_kind','vaccine','source_id',(select id from fx where k='vaccine'),'source_version',1,'review_note','Synthetic native vaccine reviewed'));
select is((select count(*) from billing_invoice_items where invoice_id=(select id from fx where k='invoice')),1::bigint,'Care completion creates no second vaccine charge');
select is((select sum(quantity) from inventory_movements where lot_id=(select id from fx where k='lot')),1::numeric,'Care completion creates no second stock debit');
select correct_patient_treatment(gen_random_uuid(),(select id from fx where k='vaccine'),'Synthetic vaccine correction',null);
select is(read_patient_care_plan((select id from fx where k='vaccine-plan'),(select id from fx where k='pet'))#>>'{plan,status}','proposed','Corrected vaccine evidence stops future routine work pending review');
reset role;
update profiles set full_name='' where id='ac2e0000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select save_recurring_care_template(gen_random_uuid(),gen_random_uuid(),null,(select v from data where k='blood-default'))$$,'42501',null,'A role without a named clinician cannot approve clinical defaults');
select * from finish();rollback;
